-- Prime Arc Academy Complete Production MySQL Dump
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';

DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `migration` VARCHAR(255) NOT NULL,
  `batch` INT NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` VARCHAR(255) NOT NULL,
  `token` VARCHAR(255) NOT NULL,
  `created_at` DATETIME,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `tokenable_type` VARCHAR(255) NOT NULL,
  `tokenable_id` BIGINT NOT NULL,
  `name` LONGTEXT NOT NULL,
  `token` VARCHAR(255) NOT NULL,
  `abilities` LONGTEXT,
  `last_used_at` DATETIME,
  `expires_at` DATETIME,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `title` VARCHAR(255) NOT NULL,
  `code` VARCHAR(255) NOT NULL,
  `description` LONGTEXT,
  `category` VARCHAR(255) NOT NULL DEFAULT 'General',
  `credits` INT NOT NULL DEFAULT '3',
  `capacity` INT NOT NULL DEFAULT '30',
  `teacher_id` BIGINT,
  `status` VARCHAR(255) NOT NULL DEFAULT 'active',
  `start_date` LONGTEXT,
  `end_date` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `enrollments`;
CREATE TABLE `enrollments` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `course_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'enrolled',
  `enrolled_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `grade_letter` VARCHAR(255),
  `final_score` DECIMAL(10,2),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `submissions`;
CREATE TABLE `submissions` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `assignment_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `content` LONGTEXT NOT NULL,
  `attachment_url` VARCHAR(255),
  `submitted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `grade` DECIMAL(10,2),
  `status` VARCHAR(255) NOT NULL DEFAULT 'submitted',
  `feedback` LONGTEXT,
  `graded_by` INT,
  `graded_at` DATETIME,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fee_invoices`;
CREATE TABLE `fee_invoices` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `invoice_number` VARCHAR(255) NOT NULL,
  `student_id` BIGINT NOT NULL,
  `course_id` BIGINT,
  `title` VARCHAR(255) NOT NULL,
  `category` VARCHAR(255) NOT NULL DEFAULT 'Tuition',
  `amount` DECIMAL(10,2) NOT NULL,
  `discount` DECIMAL(10,2) NOT NULL DEFAULT '0',
  `tax` DECIMAL(10,2) NOT NULL DEFAULT '0',
  `total_due` DECIMAL(10,2) NOT NULL,
  `paid_amount` DECIMAL(10,2) NOT NULL DEFAULT '0',
  `status` VARCHAR(255) NOT NULL DEFAULT 'pending',
  `billing_type` VARCHAR(30) NOT NULL DEFAULT 'manual',
  `billing_month` VARCHAR(20) DEFAULT NULL,
  `due_date` LONGTEXT NOT NULL,
  `notes` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `fee_breakdown` LONGTEXT,
  `late_fine_amount` DECIMAL(10,2) NOT NULL DEFAULT '0',
  `installment_number` INT NOT NULL DEFAULT '1',
  `total_installments` INT NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fee_payments`;
CREATE TABLE `fee_payments` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `invoice_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `transaction_reference` VARCHAR(255) NOT NULL,
  `payment_method` VARCHAR(255) NOT NULL DEFAULT 'Card',
  `amount` DECIMAL(10,2) NOT NULL,
  `paid_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` VARCHAR(255) NOT NULL DEFAULT 'successful',
  `receipt_number` VARCHAR(255) NOT NULL,
  `received_by` INT,
  `notes` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `transaction_id` VARCHAR(255),
  `payment_gateway` VARCHAR(255) NOT NULL DEFAULT 'UPI',
  `upi_vpa` VARCHAR(255),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `academic_classes`;
CREATE TABLE `academic_classes` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `grade_level` INT NOT NULL,
  `section` VARCHAR(255) NOT NULL DEFAULT 'A',
  `academic_year` VARCHAR(255) NOT NULL DEFAULT '2026-2027',
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `academic_subjects`;
CREATE TABLE `academic_subjects` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `class_id` BIGINT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `code` VARCHAR(255) NOT NULL,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `curriculum_topics`;
CREATE TABLE `curriculum_topics` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `subject_id` BIGINT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `chapter_number` INT,
  `subtopics` LONGTEXT,
  `description` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `status` VARCHAR(255) NOT NULL DEFAULT 'not_started',
  `completed_at` DATETIME,
  `study_notes` LONGTEXT,
  `resource_url` VARCHAR(255),
  `activity_checklist` LONGTEXT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `topic_bloom_activities`;
CREATE TABLE `topic_bloom_activities` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `topic_id` BIGINT NOT NULL,
  `bloom_level` INT NOT NULL,
  `level_name` VARCHAR(255) NOT NULL,
  `verb_keywords` VARCHAR(255),
  `activity_prompt` LONGTEXT NOT NULL,
  `rubric_guide` LONGTEXT,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `class_enrollments`;
CREATE TABLE `class_enrollments` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `class_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `roll_number` INT NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'active',
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `daily_lessons`;
CREATE TABLE `daily_lessons` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `class_id` BIGINT NOT NULL,
  `subject_id` BIGINT NOT NULL,
  `topic_id` BIGINT NOT NULL,
  `teacher_id` BIGINT NOT NULL,
  `subtopic` VARCHAR(255),
