  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bloom_assignments`;
CREATE TABLE `bloom_assignments` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `lesson_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `roll_number` INT NOT NULL,
  `bloom_level` INT NOT NULL,
  `level_name` VARCHAR(255) NOT NULL,
  `activity_prompt` LONGTEXT NOT NULL,
  `submission_content` LONGTEXT,
  `submitted_at` DATETIME,
  `status` VARCHAR(255) NOT NULL DEFAULT 'assigned',
  `teacher_feedback` LONGTEXT,
  `score` DECIMAL(10,2),
  `reviewed_by` INT,
  `reviewed_at` DATETIME,
  `created_at` DATETIME,
  `updated_at` DATETIME,
  `due_date` LONGTEXT,
