) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `attendance_sessions`;
CREATE TABLE `attendance_sessions` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `class_id` BIGINT,
  `course_id` BIGINT,
