  `option_c` VARCHAR(255) NOT NULL,
  `option_d` VARCHAR(255) NOT NULL,
  `correct_option` VARCHAR(255) NOT NULL,
  `explanation` LONGTEXT NOT NULL,
  `marks` INT NOT NULL DEFAULT '4',
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dpp_submissions`;
CREATE TABLE `dpp_submissions` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT,
  `dpp_id` BIGINT NOT NULL,
  `student_id` BIGINT NOT NULL,
  `answers` LONGTEXT NOT NULL,
  `score` INT NOT NULL DEFAULT '0',
  `max_score` INT NOT NULL DEFAULT '20',
  `percentage` DECIMAL(10,2) NOT NULL DEFAULT '0',
  `xp_earned` INT NOT NULL DEFAULT '30',
  `checked_at` DATETIME NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'evaluated',
  `created_at` DATETIME,
