(1, 1, 'Combustion and Flame', 4, '["Ignition temperature & inflammable substances","CO2 vs Water fire extinguishers","Three zones of candle flame (dark, luminous, non-luminous)","Calorific value of fuels (kJ\\/kg)"]', 'Conditions for combustion (fuel, oxygen, ignition temperature), types of combustion, fire extinguishers, zones of candle flame.', '2026-10-30 05:27:23', '2026-10-30 05:28:05', 'completed', '2026-10-30 05:28:05', NULL, 'https://ncert.nic.in/textbook.php', NULL),
(2, 2, 'Linear Equations in One Variable', 2, '["Equations with variable on one side","Equations with variables on both sides","Linear reduction by cross-multiplication","Age and digit word problems"]', 'Solving linear equations with variables on one side and both sides, cross-multiplication applications.', '2026-10-30 05:27:23', '2026-10-30 05:28:05', 'completed', '2026-10-28 05:28:05', NULL, 'https://ncert.nic.in/textbook.php', NULL),
(3, 4, 'Heat and Temperature', 3, '["Clinical thermometer kink & range","Conduction in solids (metals)","Convection currents in fluids\\/sea breeze","Radiation through vacuum"]', 'Clinical vs laboratory thermometers, Celsius and Fahrenheit scales, conduction, convection, radiation.', '2026-10-30 05:27:23', '2026-10-30 05:28:05', 'completed', '2026-10-26 05:28:05', NULL, 'https://ncert.nic.in/textbook.php', NULL),
