(385, 62, 'Statistics', 13, '["Mean deviation about mean and median","Variance formula \\u03c3\\u00b2 = 1\\/N \\u00b7 \\u03a3fi(xi - x\\u0304)\\u00b2","Standard deviation \\u03c3 and shortcut method","Coefficient of variation comparison"]', 'Measures of dispersion: range, mean deviation about mean, mean deviation about median, variance and standard deviation of grouped data.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(386, 62, 'Probability', 14, '["Sample space generation for complex experiments","Mutually exclusive and exhaustive events","Axiomatic probability conditions","Addition theorem P(A \\u222a B) = P(A) + P(B) - P(A \\u2229 B)"]', 'Random experiments, sample space, event types (mutually exclusive, exhaustive), axiomatic approach to probability, addition theorem P(A ∪ B).', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(387, 63, 'Diversity in the Living World', 1, '["Characteristics of life and homeostasis","Binomial nomenclature by Carl Linnaeus","Taxonomic categories from species to kingdom","Botanical gardens, herbaria, museums, keys"]', 'What is living, biodiversity, taxonomic hierarchy (kingdom, phylum, class, order, family, genus, species), binomial nomenclature.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(388, 63, 'Biological Classification', 2, '["Kingdom Monera: Archaebacteria and Eubacteria","Kingdom Protista: Chrysophytes, Dinoflagellates, Protozoa","Kingdom Fungi: Phycomycetes, Ascomycetes, Basidiomycetes","Acellular agents: Viruses, Viroids, Prions, Lichens"]', 'Five kingdom classification (Whittaker): Monera, Protista, Fungi, Plantae, Animalia; viruses, viroids, prions, lichens.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(389, 63, 'Cell: The Unit of Life', 3, '["Cell Theory by Schleiden and Schwann","Singer-Nicolson Fluid Mosaic membrane model","Endomembrane: ER, Golgi, Lysosomes, Vacuoles","Semiconservative DNA in Mitochondria & Plastids"]', 'Cell theory, prokaryotic vs eukaryotic cell, fluid mosaic model of plasma membrane, endomembrane system, mitochondria, chloroplasts, nucleus.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(390, 63, 'Biomolecules', 4, '["Monosaccharides and Glycosidic bonds","Phospholipids and Triglyceride structure","Peptide bond and Protein structural hierarchy","Enzyme active site, Michaelis constant Km, inhibition"]', 'Chemical analysis of living tissues, carbohydrates, lipids, proteins (primary to quaternary structure), nucleic acids, enzymes and enzyme kinetics.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(391, 63, 'Cell Cycle and Cell Division', 5, '["Interphase and DNA replication in S phase","Mitotic spindle assembly and chromosome separation","Meiosis I Prophase I stages (Leptotene to Diakinesis)","Synaptonemal complex and Crossing over"]', 'Phases of cell cycle (G1, S, G2, M), Mitosis stages (prophase, metaphase, anaphase, telophase), Meiosis I and II, crossing over, significance.', '2026-10-30 05:27:55', '2026-10-30 05:27:55', 'not_started', NULL, NULL, NULL, NULL),
(392, 63, 'Photosynthesis in Higher Plants', 6, '["Light harvesting complexes (PSI & PSII)","Chemiosmotic ATP synthesis hypothesis","Calvin Cycle (Carboxylation, Reduction, Regeneration)","Kranz anatomy in C4 plants and Photorespiration"]', 'Chloroplast structure, pigments, light reactions, Z-scheme of electron transport, photophosphorylation, Calvin cycle (C3), Hatch-Slack pathway (C4).', '2026-10-30 05:27:56', '2026-10-30 05:27:56', 'not_started', NULL, NULL, NULL, NULL),
