INSERT INTO `live_quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `points`, `created_at`, `updated_at`) VALUES
(4, 2, 'What is the SI unit of gravitational potential energy?', 'Newton (N)', 'Joule (J)', 'Watt (W)', 'Pascal (Pa)', 'B', 'Energy in all forms (kinetic, potential, thermal) is measured in Joules (J = kg·m²/s²).', 10, '2026-11-03 16:24:49', '2026-11-03 16:24:49'),
(5, 2, 'When a body moves with constant velocity, its net external acceleration is:', 'Zero', '9.8 m/s²', 'Infinite', 'Proportional to its mass', 'A', 'According to Newton\'s First Law, constant velocity implies zero net change in velocity (a = dv/dt = 0).', 10, '2026-11-03 16:24:49', '2026-11-03 16:24:49'),
(6, 2, 'Which of the following electromagnetic waves has the highest frequency?', 'Microwaves', 'Ultraviolet', 'Gamma rays', 'Infrared', 'C', 'Gamma rays reside at the highest energy and frequency end of the electromagnetic spectrum.', 10, '2026-11-03 16:24:49', '2026-11-03 16:24:49');
INSERT INTO `academic_projects` (`id`, `class_id`, `subject_id`, `teacher_id`, `title`, `type`, `group_mode`, `max_team_size`, `description`, `problem_statement`, `evaluation_rubric`, `due_date`, `max_marks`, `created_at`, `updated_at`) VALUES
(3, 8, 1, 18, 'Smart City Autonomous Traffic Flow Optimization', 'project', 'grouped', 4, 'Design an automated traffic sequencing model using graph theory and sensor feedback to minimize metropolitan vehicle wait times.', 'Urban density creates bottlenecks at arterial junctions. Model an adaptive signal algorithm that reacts dynamically to vehicular queue density.', 'Mathematical formulation (30%), simulation code/diagrams (40%), final presentation & team synergy (30%).', '2026-11-24 00:00:00', 100, '2026-11-03 16:24:49', '2026-11-03 16:24:49'),
(4, 8, 1, 18, 'Quantum Tunneling in Modern Semiconductor Nanostructures', 'case_study', 'individual', 1, 'Comprehensive analytical study investigating quantum leakage in sub-3nm FinFET and Gate-All-Around (GAA) transistor architectures.', 'As gate oxide thicknesses drop below 1.5 nanometers, wave-packet tunneling limits traditional gate insulation. Propose alternate high-k dielectric solutions.', 'Literature review (25%), physical equations (35%), proposed solution feasibility (40%).', '2026-11-17 00:00:00', 75, '2026-11-03 16:24:49', '2026-11-03 16:24:49');
