(3, 18, 'Prime Arc National Parliamentary Debate 2026', 'debate', 'parliamentary_team', 'Official Asian Parliamentary format debate tournament. Motion: "This House Would Mandate Algorithmic Transparency in Educational Grading."', '7-minute constructive speeches, 3-minute whip replies. Points of Information (POIs) accepted between minutes 1 and 6.', '2026-11-08 14:00:00', 'Chanakya Central Auditorium & Global Stream', 'upcoming', '[19]', '{"1st":"Quantum Orators (Class 10-A)","2nd":"Dialectic Pioneers (Class 9-B)","3rd":"The Rhetoricians (Class 8-A)"}', '2026-11-03 16:24:49', '2026-11-03 16:24:49'),
(4, 18, 'Prime Arc Innovation & Creative Talent Showcase 2026', 'talent_show', 'individual', 'Annual multidisciplinary talent exhibition celebrating scientific invention, digital arts, classical instrumentation, and dramatic monologues.', 'Maximum 5-minute performance or live prototype demonstration judged on originality, technical execution, and stage impact.', '2026-11-15 16:30:00', 'Rabindranath Tagore Cultural Center & Amphitheatre', 'upcoming', '[]', NULL, '2026-11-03 16:24:49', '2026-11-03 16:24:49');
