INSERT INTO `course_modules` (`id`, `course_id`, `week_number`, `title`, `theme`, `description`, `learning_goals`, `order_index`, `created_at`, `updated_at`) VALUES
(83, 22, 1, 'Module 1: Foundations & Phonics Mastery', 'Basics of English, Alphabet, Greetings, Etiquette, Vowel & Consonant Phonics, Daily Vocabulary', 'Master the bedrock fundamentals of the English language: letter phonetics, conversational greetings, social etiquette, standard pronunciation rules, and high-frequency vocabulary.', NULL, 1, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(84, 22, 3, 'Module 2: Sentence Building Blocks & Parts of Speech', 'WH Questions, 8 Parts of Speech, Nouns, Pronouns, Adjectives, Verbs, Adverbs, Articles, Prepositions & Determiners', 'Comprehensive mastery of the 8 parts of speech and structural building blocks: question formation, noun genders/numbers, pronoun cases, verb forms, adverbial modification, and relational prepositions.', NULL, 2, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(85, 22, 6, 'Module 3: Non-Action Sentences, Existence & Spatial States', 'Simple Sentences (Present, Past, Future Categories I & II), Concept of There, Position Sense', 'Express states of being, identity, possession, and existence without action verbs. Complete command over Is/Am/Are, Has/Have, Was/Were, Had, Will be/have, There, and spatial positioning.', NULL, 3, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(86, 22, 7, 'Module 4: The 12 English Tenses & Temporal Mastery', '12 English Tenses: Indefinite, Continuous, Perfect, Perfect Continuous across Present, Past & Future', 'Rigorous deep-dive into the entire temporal system of English: all 12 tenses, timeline markers, auxiliary shifts, and extensive translation drills.', NULL, 4, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(87, 22, 8, 'Module 5: Advanced Functional Auxiliaries, Voice & Causatives', 'Usage of It, Modals, Conjunctions, Imperatives, Let, Causative Verbs (Get/Make), Passive Voice & Special Cases', 'Elevate speaking ability with modern conversational mechanics: modal degrees, dummy subject It, causative actions with Get and Make, imperative instructions, and active-passive voice.', NULL, 5, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(88, 22, 11, 'Module 6: Conversational Fluency & Vocabulary Precision', 'Sentence Fillers, Question Tags, Phrasal Verbs, Prepositional Phrases, Homophones, One Word Substitutions', 'Speak with natural English flow, cadence, and nuance: filler words, intonation tags, colloquial phrasal verbs, idioms, and precise one-word vocabulary.', NULL, 6, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(89, 22, 13, 'Module 7: Applied Practice, Error Correction & Translation', 'Hindi-English Translation, Objective MCQs, Syntax Error Spotting, Mixed Practice & Mock Benchmarks', 'Rigorous testing and reinforcement drills: bi-directional translation, objective error detection, syntax correction, and full-length assessment papers.', NULL, 7, '2026-11-04 14:40:35', '2026-11-04 14:40:35'),
(90, 22, 15, 'Module 8: Real-Life Spoken Scenarios, Listening & Professional Interviews', '30 Situational Roleplays, Passage Listening, Idioms & Proverbs, Certification, Job Interview Q&A, Dictionary', 'Practical communication mastery: 30 live conversation roleplays (Doctor, Shopping, Banking, Hotel, Social), job interview preparation, spoken assessment, and complete English-Hindi dictionary.', NULL, 8, '2026-11-04 14:40:35', '2026-11-04 14:40:35');
INSERT INTO `course_lessons` (`id`, `course_id`, `module_id`, `lesson_number`, `week_number`, `day_of_week`, `title`, `duration_minutes`, `level`, `topic_summary`, `learning_objectives`, `expected_outcomes`, `vocabulary`, `concepts`, `teaching_materials`, `time_allocation`, `procedure_steps`, `speaking_activity`, `listening_activity`, `reading_activity`, `writing_activity`, `real_life_scenario`, `common_mistakes`, `homework_task`, `evaluation_criteria`, `teacher_script`, `worksheet`, `answer_key`, `order_index`, `created_at`, `updated_at`, `class_notes`, `pdf_url`, `video_url`) VALUES
(404, 22, 83, 1, 1, 'Monday', 'Lesson 1: Before We Start', 45, 'beginner', 'Lesson 1 Foundations Masterclass: Core English linguistic building blocks, Alphabet vs. 26 Letters distinction, time-based greetings matrix, 7 pillars of polite etiquette, precision time-telling formulas (past/to), teen vs ty numeral phonetics, punctuation rules, and time prepositions (at, on, in). Fully bilingual (English & Hindi) designed for Indian professionals.', '["Understand that English has exactly 1 Alphabet containing 26 letters (5 vowels, 21 consonants) creating 44 distinct sounds.","Master formal and informal greetings across time brackets (Morning, Afternoon, Evening, Night).","Apply the 7 Golden Rules of Polite Etiquette (Please, Thank you, You are welcome, Excuse me, Pardon, After you, Allow me).","Tell clock time accurately using the [Minutes + PAST\\/TO + Hour] formula and avoid the MTI clock-in trap.","Distinguish teen vs ty stress patterns and spell 40 (Forty) correctly.","Correctly apply prepositions of time: AT for clock times, ON for days and dates, IN for months and years."]', '["Confidence to introduce greetings and handle everyday courtesies without Hindi Mother Tongue Influence (MTI).","Zero ambiguity when reading or saying 14 vs 40, 15 vs 50, etc.","Correct time-telling by watch without using in my watch.","Accurate capitalization and punctuation usage in everyday written communication."]', '[{"term":"Alphabet","phonetic":"\\/\\u02c8\\u00e6lf\\u0259b\\u025bt\\/","meaning":"A set of letters arranged in a fixed order (\\u0935\\u0930\\u094d\\u0923\\u092e\\u093e\\u0932\\u093e)"},{"term":"Etiquette","phonetic":"\\/\\u02c8\\u025bt\\u026ak\\u025bt\\/","meaning":"Rules of polite and acceptable behavior (\\u0936\\u093f\\u0937\\u094d\\u091f\\u093e\\u091a\\u093e\\u0930)"},{"term":"O\'clock","phonetic":"\\/\\u0259\\u02c8kl\\u0252k\\/","meaning":"Of the clock; exact point of hour (\\u092c\\u091c\\u0947)"},{"term":"Quarter","phonetic":"\\/\\u02c8kw\\u0254\\u02d0t\\u0259\\/","meaning":"One-fourth; 15 minutes in time telling (\\u0938\\u0935\\u093e \\/ \\u092a\\u094c\\u0928\\u0947)"},{"term":"Half","phonetic":"\\/h\\u0251\\u02d0f\\/","meaning":"30 minutes in time telling (\\u0938\\u093e\\u0922\\u093c\\u0947)"},{"term":"Fortnight","phonetic":"\\/\\u02c8f\\u0254\\u02d0tna\\u026at\\/","meaning":"A period of two weeks (\\u0926\\u094b \\u0938\\u092a\\u094d\\u0924\\u093e\\u0939 \\/ \\u092a\\u0916\\u0935\\u093e\\u0921\\u093c\\u093e)"}]', '"Textbook Reference Pages 8 to 17 (10 pages). Complete study material extracted from Spoken English Guru eBook."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"mistake":"Saying Good night upon arrival in the evening.","correction":"Always say Good evening on arrival, even at 10:00 PM. Good night is strictly for parting\\/farewell."},{"mistake":"What is the time in your watch?","correction":"What is the time BY your watch? (by specifies measuring instrument)."},{"mistake":"Writing Fourty.","correction":"Spell FORTY (f-o-r-t-y, drop the u)."},{"mistake":"Pronouncing Wednesday as Wed-nes-day.","correction":"Pronounce as WENZ-day (d is silent)."},{"mistake":"I was born on 1995.","correction":"I was born IN 1995 (IN for years\\/months; ON for specific dates\\/days)."}]', '/uploads/course_dpps/DPP_01_Before_We_Start.pdf', NULL, NULL, NULL, NULL, 1, '2026-11-04 14:40:35', '2026-11-04 15:26:06', '{"handout_title": "Spoken English 2.0 Enhanced Notes - Lesson 1: Before We Start", "pdf_path": "/uploads/course_notes/Lesson_01_Before_We_Start_Enhanced.pdf", "page_count": 15, "format": "PrimeArc Mobile Notes (390 x 780 pt)", "watermark": "PrimeArc Geometric", "null_glyphs": 0}', '/uploads/course_notes/lesson_01_before_we_start.pdf', 'https://www.youtube.com/watch?v=8jLOx1hD3_o'),
(405, 22, 83, 2, 1, 'Wednesday', 'Lesson 2: Few Basics of English', 50, 'beginner', 'Few Basics of English: Sentence Types, Parts of Sentence, Subject Types, 1st/2nd/3rd Person, This/That/These/Those, Living vs Non-Living, Apostrophe s. 18 Lesson – 2 Few Basics of English (vaxzst+h dh dqN ewy ckrsa) –{vkWfM;ks ySDpj Hkh lqfu;s} Sentences ¼okD;½ gj Hkk’kk esa d...', '"Master the core grammatical and spoken mechanics of: Sentence Types, Parts of Sentence, Subject Types, 1st\\/2nd\\/3rd Person, This\\/That\\/These\\/Those, Living vs Non-Living, Apostrophe s"', 'Confident command of spoken sentences, pronunciation, and written application for Lesson 2: Few Basics of English', '"Sentence Types, Parts of Sentence, Subject Types, 1st\\/2nd\\/3rd Person, This\\/That\\/These\\/Those, Living vs Non-Living, Apostrophe s"', '"Textbook Reference Pages 18 to 28 (11 pages). Complete study material extracted from Spoken English Guru eBook."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/uploads/course_dpps/DPP_02_Few_Basics_of_English.pdf', NULL, NULL, NULL, NULL, 2, '2026-11-04 14:40:59', '2026-11-04 14:40:59', '{"handout_title": "Spoken English 2.0 Enhanced Notes - Lesson 2: Few Basics of English", "pdf_path": "/uploads/course_notes/Lesson_02_Few_Basics_of_English_Enhanced.pdf", "page_count": 16, "format": "PrimeArc Mobile Notes (390 x 780 pt)", "watermark": "PrimeArc Geometric", "null_glyphs": 0}', '/uploads/course_notes/lesson_02_few_basics_of_english.pdf', 'https://www.youtube.com/watch?v=v9ejT8FO-7I'),
